// The directory paragraphs contain the English source for both artwork surfaces.
const brandDescriptionCopy = {
  mili: {
    'zh-Hans': '查看 MILI 官方品牌封面图。虚拟料理台展示 MILI 蚝油（510 克）、素食蚝油（510 克）和素鸭（280 克）的无印刷包装模型。',
    ms: 'Lihat ilustrasi kulit hadapan rasmi jenama MILI. Kaunter masakan maya mempamerkan model tanpa cetakan label bagi Sos Tiram MILI (510 g), Sos Tiram Vegetarian (510 g) dan Itik Tiruan Vegetarian (280 g).',
  },
  gogo: {
    'zh-Hans': '查看 GOGO 官方饮料封面图。虚拟冰淇淋车展示无包装的 potong 冰淇淋模型，呈现新加坡保健促进局于 2016 年记录的什锦水果和红豆口味。',
    ms: 'Lihat ilustrasi kulit hadapan rasmi untuk minuman GOGO. Di gerai maya, model ais krim potong tanpa pembalut mewakili perisa Aneka Buah Asli dan Kacang Merah yang direkodkan oleh Lembaga Penggalakan Kesihatan Singapura pada tahun 2016.',
  },
};

const attributes = ['aria-label','title','placeholder','alt'];
const originals = new WeakMap();
let language = 'en';
function translate(source) {
  const key = source.trim();
  let output = messages.get(key)?.[language];
  const themeCopy = MALL_THEME_COPY[language];
  if (!output && Object.hasOwn(themeCopy,key)) output = themeCopy[key];
  if (!output && language !== 'en') {
    for (const [pattern, chinese, malay] of patterns) {
      if (pattern.test(key)) { output = key.replace(pattern, language === 'ms' ? malay : chinese); break; }
    }
  }
  return output ? source.replace(key, () => output) : source;
}
function render(node, attribute) {
  const current = attribute ? node.getAttribute(attribute) : node.data;
  if (!current || !current.trim()) return;
  let values = originals.get(node);
  const previous = values?.get(attribute);
  const source = previous?.output === current ? previous.source : current;
  const brand = !attribute && node.parentElement?.dataset.brandDescription;
  const output = brandDescriptionCopy[brand]?.[language] ?? translate(source);
  if (output === current && !previous) return;
  if (!values) { values = new Map(); originals.set(node, values); }
  values.set(attribute, {source, output});
  if (output !== current) {
    if (attribute) node.setAttribute(attribute, output);
    else node.data = output;
  }
}
function visit(node) {
  if (node.nodeType === Node.TEXT_NODE) { render(node); return; }
  if (node.nodeType !== Node.ELEMENT_NODE || node.matches('script,style,noscript,[translate=no]')) return;
  for (const attribute of attributes) if (node.hasAttribute(attribute)) render(node, attribute);
  for (const child of node.childNodes) visit(child);
}
const observer = new MutationObserver(records => {
  for (const record of records) {
    if (record.type === 'attributes') render(record.target, record.attributeName);
    else if (record.type === 'characterData') render(record.target);
    else for (const child of record.addedNodes) visit(child);
  }
});
const selectors = document.querySelectorAll('[data-mall-language]');
const headerCode = document.getElementById('site-language-code');
function setLanguage(code) {
  observer.disconnect();
  language = ['zh-Hans','ms'].includes(code) ? code : 'en';
  document.documentElement.lang = language;
  headerCode.textContent = language === 'zh-Hans' ? '中' : language.toUpperCase();
  for (const select of selectors) select.value = language;
  visit(document.documentElement);
  if (language !== 'en') observer.observe(document.body, {subtree:true, childList:true, characterData:true, attributes:true, attributeFilter:attributes});
  window.dispatchEvent(new Event('mall:languagechange'));
}
let preferred = 'en';
try { preferred = localStorage.getItem('wdg.language'); } catch { /* Session only. */ }
setLanguage(preferred);
for (const select of selectors) select.addEventListener('change', () => {
  setLanguage(select.value);
  try { localStorage.setItem('wdg.language',language); } catch { /* Session only. */ }
});
window.addEventListener('storage', event => { if (event.key === 'wdg.language') setLanguage(event.newValue); });
